ALTER TABLE public.club_bar_settings ADD COLUMN tips_enabled boolean NOT NULL DEFAULT false, ADD COLUMN cash_up_enabled boolean NOT NULL DEFAULT false, ADD COLUMN online_tips_ready boolean NOT NULL DEFAULT false;
CREATE TABLE public.bar_tips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),club_id uuid NOT NULL REFERENCES public.clubs(id),tab_id uuid UNIQUE REFERENCES public.bar_guest_tabs(id),sale_id uuid UNIQUE REFERENCES public.bar_visitor_sales(id),staff_id uuid NOT NULL REFERENCES public.bar_counter_devices(id),staff_name text NOT NULL,amount numeric(12,2) NOT NULL CHECK(amount>0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','account_due','earned','cancelled')),method text,club_member_id uuid,created_at timestamptz NOT NULL DEFAULT now(),earned_at timestamptz,CHECK((tab_id IS NOT NULL)::int+(sale_id IS NOT NULL)::int=1));
GRANT SELECT ON public.bar_tips TO authenticated;
GRANT ALL ON public.bar_tips TO service_role;
ALTER TABLE public.bar_tips ENABLE ROW LEVEL SECURITY;
CREATE POLICY bar_tip_read ON public.bar_tips FOR SELECT TO authenticated USING(public.is_club_admin_or_permitted(auth.uid(),club_id,'bar') OR public.has_club_permission(auth.uid(),club_id,'finance'));
CREATE TABLE public.bar_tip_payouts(id uuid PRIMARY KEY,club_id uuid NOT NULL REFERENCES public.clubs(id),staff_id uuid NOT NULL REFERENCES public.bar_counter_devices(id),staff_name text NOT NULL,amount numeric(12,2) NOT NULL CHECK(amount>0),method text NOT NULL DEFAULT 'cash' CHECK(method='cash'),actor_user_id uuid,actor_device_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bar_tip_payouts TO authenticated;
GRANT ALL ON public.bar_tip_payouts TO service_role;
ALTER TABLE public.bar_tip_payouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY bar_tip_payout_read ON public.bar_tip_payouts FOR SELECT TO authenticated USING(public.is_club_admin_or_permitted(auth.uid(),club_id,'bar') OR public.has_club_permission(auth.uid(),club_id,'finance'));
CREATE FUNCTION public.bar_tip_config(_club_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('enabled',coalesce(s.tips_enabled,false),'cash_up_enabled',coalesce(s.cash_up_enabled,false),'online_tips_ready',coalesce(s.online_tips_ready,false),'staff',CASE WHEN coalesce(s.tips_enabled,false) THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'name',d.label) ORDER BY d.label) FROM bar_counter_devices d WHERE d.club_id=c.id AND d.active AND nullif(btrim(d.label),'') IS NOT NULL),'[]'::jsonb) ELSE '[]'::jsonb END) FROM clubs c LEFT JOIN club_bar_settings s ON s.club_id=c.id WHERE c.id=_club_id; $$;
GRANT EXECUTE ON FUNCTION public.bar_tip_config(uuid) TO anon,authenticated,service_role;
CREATE FUNCTION public.bar_set_tip_switch(_club_id uuid,_key text,_value boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce((public.is_club_admin_or_permitted(auth.uid(),_club_id,'bar') OR public.has_role(auth.uid(),'admin')),false) THEN RAISE EXCEPTION 'Bar management permission required'; END IF; IF _key NOT IN ('tips_enabled','cash_up_enabled') THEN RAISE EXCEPTION 'Unknown setting'; END IF; INSERT INTO club_bar_settings(club_id) VALUES(_club_id) ON CONFLICT(club_id) DO NOTHING; IF _key='tips_enabled' THEN UPDATE club_bar_settings SET tips_enabled=_value,updated_at=now() WHERE club_id=_club_id; ELSE UPDATE club_bar_settings SET cash_up_enabled=_value,updated_at=now() WHERE club_id=_club_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.bar_set_tip_switch(uuid,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.bar_set_tip_switch(uuid,text,boolean) TO authenticated;
CREATE FUNCTION public._bar_prepare_tip(_club uuid,_tab uuid,_sale uuid,_amount numeric,_staff uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n text; BEGIN IF _amount IS NULL OR _amount<0 OR _amount::text IN ('NaN','Infinity','-Infinity') OR _amount<>round(_amount,2) THEN RAISE EXCEPTION 'Invalid tip amount'; END IF; IF _amount=0 THEN UPDATE bar_tips SET status='cancelled' WHERE (tab_id=_tab OR sale_id=_sale) AND status='pending'; RETURN; END IF; IF NOT EXISTS(SELECT 1 FROM club_bar_settings WHERE club_id=_club AND tips_enabled) THEN RAISE EXCEPTION 'Tips are not enabled'; END IF; SELECT label INTO n FROM bar_counter_devices WHERE id=_staff AND club_id=_club AND active FOR UPDATE; IF n IS NULL OR nullif(btrim(n),'') IS NULL THEN RAISE EXCEPTION 'Choose a valid serving person'; END IF; IF _tab IS NOT NULL THEN INSERT INTO bar_tips(club_id,tab_id,staff_id,staff_name,amount) VALUES(_club,_tab,_staff,n,_amount) ON CONFLICT(tab_id) DO UPDATE SET staff_id=excluded.staff_id,staff_name=excluded.staff_name,amount=excluded.amount,status='pending' WHERE bar_tips.status IN ('pending','cancelled'); ELSE INSERT INTO bar_tips(club_id,sale_id,staff_id,staff_name,amount) VALUES(_club,_sale,_staff,n,_amount); END IF; END $$;
REVOKE ALL ON FUNCTION public._bar_prepare_tip(uuid,uuid,uuid,numeric,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.bar_set_tab_tip(_tab_id uuid,_tab_token uuid,_amount numeric,_staff_id uuid,_counter_token uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t bar_guest_tabs;c uuid;recipient uuid:=_staff_id; BEGIN SELECT * INTO t FROM bar_guest_tabs WHERE id=_tab_id FOR UPDATE; IF NOT FOUND OR t.status<>'open' THEN RAISE EXCEPTION 'Only open tabs can change tips'; END IF; IF _counter_token IS NOT NULL THEN c:=bar_counter_context(_counter_token,NULL); IF c IS DISTINCT FROM t.club_id OR NOT EXISTS(SELECT 1 FROM bar_counter_sessions s JOIN bar_counter_devices d ON d.id=s.device_id WHERE s.token=_counter_token AND d.active AND s.revoked_at IS NULL AND s.expires_at>now() AND nullif(btrim(d.label),'') IS NOT NULL) THEN RAISE EXCEPTION 'Personal counter PIN required'; END IF; SELECT device_id INTO recipient FROM bar_counter_sessions WHERE token=_counter_token AND club_id=c AND revoked_at IS NULL AND expires_at>now(); ELSIF _tab_token IS DISTINCT FROM t.token THEN RAISE EXCEPTION 'Tab not found'; END IF; PERFORM _bar_prepare_tip(t.club_id,t.id,NULL,_amount,recipient); END $$;
GRANT EXECUTE ON FUNCTION public.bar_set_tab_tip(uuid,uuid,numeric,uuid,uuid) TO anon,authenticated;
CREATE FUNCTION public._bar_recognise_account_tips(_club uuid,_member uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t bar_tips;owing numeric;ref uuid; BEGIN PERFORM 1 FROM club_members WHERE id=_member AND club_id=_club FOR UPDATE; SELECT coalesce(sum(debit-credit),0) INTO owing FROM club_journal_entries WHERE club_id=_club AND club_member_id=_member AND account IN ('debtors','member_credits'); IF owing>0 THEN RETURN; END IF; FOR t IN SELECT * FROM bar_tips WHERE club_id=_club AND club_member_id=_member AND status='account_due' ORDER BY id FOR UPDATE LOOP PERFORM 1 FROM bar_counter_devices WHERE id=t.staff_id FOR UPDATE; ref:=gen_random_uuid(); INSERT INTO club_journal_entries(club_id,journal_ref,account,debit,credit,description) VALUES(_club,ref,'creditors',t.amount,0,'Tip received — '||t.staff_name),(_club,ref,'bar_income',0,t.amount,'Tip income — '||t.staff_name); UPDATE bar_tips SET status='earned',earned_at=now() WHERE id=t.id; END LOOP; END $$;
REVOKE ALL ON FUNCTION public._bar_recognise_account_tips(uuid,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public._bar_tip_account_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.club_member_id IS NOT NULL AND NEW.account IN ('debtors','member_credits') AND NEW.credit>0 THEN PERFORM _bar_recognise_account_tips(NEW.club_id,NEW.club_member_id); END IF; RETURN NEW; END $$;
CREATE TRIGGER bar_tip_account_payment AFTER INSERT ON public.club_journal_entries FOR EACH ROW EXECUTE FUNCTION public._bar_tip_account_payment();
REVOKE ALL ON FUNCTION public._bar_tip_account_payment() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public._bar_earn_tip(_id uuid,_method text,_member uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t bar_tips;asset gl_account;g record; BEGIN SELECT * INTO t FROM bar_tips WHERE id=_id FOR UPDATE; IF NOT FOUND OR t.status<>'pending' THEN RETURN; END IF; IF _method='online' AND NOT EXISTS(SELECT 1 FROM club_bar_settings WHERE club_id=t.club_id AND online_tips_ready) THEN RAISE EXCEPTION 'Online tip payment release is not enabled'; END IF; PERFORM 1 FROM bar_counter_devices WHERE id=t.staff_id FOR UPDATE; asset:=CASE WHEN _method='cash' THEN 'cash'::gl_account WHEN _method='member_account' THEN 'debtors'::gl_account ELSE 'bank_current'::gl_account END; IF _method='member_account' THEN IF _member IS NULL OR NOT EXISTS(SELECT 1 FROM club_members WHERE id=_member AND club_id=t.club_id AND status='active') THEN RAISE EXCEPTION 'Member not found'; END IF; PERFORM 1 FROM club_members WHERE id=_member FOR UPDATE; IF EXISTS(SELECT 1 FROM club_bar_settings WHERE club_id=t.club_id AND bar_allow_member_debit=false) THEN SELECT * INTO g FROM member_account_gate(_member,t.amount); IF g.shortfall>0 THEN RAISE EXCEPTION 'ACCOUNT_LIMIT|%|%|%',g.shortfall,g.projected_owing,g.allowance; END IF; END IF; END IF; INSERT INTO club_journal_entries(club_id,journal_ref,account,debit,credit,description,club_member_id) VALUES(t.club_id,t.id,asset,t.amount,0,CASE WHEN _method='member_account' THEN 'Tip charged — ' ELSE 'Tip income — ' END||t.staff_name,CASE WHEN _method='member_account' THEN _member END),(t.club_id,t.id,CASE WHEN _method='member_account' THEN 'creditors'::gl_account ELSE 'bar_income'::gl_account END,0,t.amount,CASE WHEN _method='member_account' THEN 'Tip charged — ' ELSE 'Tip income — ' END||t.staff_name,NULL); UPDATE bar_tips SET status=CASE WHEN _method='member_account' THEN 'account_due' ELSE 'earned' END,earned_at=CASE WHEN _method<>'member_account' THEN now() END,method=_method,club_member_id=_member WHERE id=t.id; IF _method='member_account' THEN PERFORM _bar_recognise_account_tips(t.club_id,_member); END IF; END $$;
REVOKE ALL ON FUNCTION public._bar_earn_tip(uuid,text,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public._bar_tip_tab_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tip uuid; BEGIN IF NEW.status IN ('settled','closed') AND OLD.status NOT IN ('settled','closed') THEN SELECT id INTO tip FROM bar_tips WHERE tab_id=NEW.id AND status='pending'; IF tip IS NOT NULL THEN PERFORM _bar_earn_tip(tip,NEW.settled_method,NEW.club_member_id); END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER bar_tip_tab_state AFTER UPDATE OF status ON public.bar_guest_tabs FOR EACH ROW EXECUTE FUNCTION public._bar_tip_tab_state();
CREATE FUNCTION public._bar_tip_sale_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tip uuid; BEGIN SELECT id INTO tip FROM bar_tips WHERE sale_id=NEW.id AND status='pending'; IF tip IS NOT NULL AND NEW.payment_status='paid' THEN PERFORM _bar_earn_tip(tip,NEW.payment_method); ELSIF tip IS NOT NULL AND NEW.payment_status='failed' THEN UPDATE bar_tips SET status='cancelled' WHERE id=tip; END IF; RETURN NEW; END $$;
CREATE TRIGGER bar_tip_sale_state AFTER UPDATE OF payment_status ON public.bar_visitor_sales FOR EACH ROW EXECUTE FUNCTION public._bar_tip_sale_state();
CREATE FUNCTION public._bar_tip_authorise(_club uuid,_token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d uuid; BEGIN IF _token IS NOT NULL THEN SELECT s.device_id INTO d FROM bar_counter_sessions s JOIN bar_counter_devices b ON b.id=s.device_id AND b.club_id=s.club_id WHERE s.token=_token AND s.club_id=_club AND s.revoked_at IS NULL AND s.expires_at>now() AND b.active AND nullif(btrim(b.label),'') IS NOT NULL; IF d IS NULL THEN RAISE EXCEPTION 'Personal counter PIN required'; END IF; ELSIF NOT coalesce((is_club_admin_or_permitted(auth.uid(),_club,'bar') OR has_club_permission(auth.uid(),_club,'finance') OR has_role(auth.uid(),'admin')),false) THEN RAISE EXCEPTION 'Bar or finance permission required'; END IF; RETURN d; END $$;
REVOKE ALL ON FUNCTION public._bar_tip_authorise(uuid,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.bar_staff_tip_balances(_club_id uuid,_token uuid DEFAULT NULL) RETURNS TABLE(staff_id uuid,name text,earned numeric,paid numeric,remaining numeric) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM _bar_tip_authorise(_club_id,_token); RETURN QUERY SELECT d.id,d.label,coalesce(t.a,0),coalesce(p.a,0),coalesce(t.a,0)-coalesce(p.a,0) FROM bar_counter_devices d LEFT JOIN(SELECT bt.staff_id,sum(bt.amount) a FROM bar_tips bt WHERE bt.club_id=_club_id AND bt.status='earned' GROUP BY bt.staff_id)t ON t.staff_id=d.id LEFT JOIN(SELECT bp.staff_id,sum(bp.amount) a FROM bar_tip_payouts bp WHERE bp.club_id=_club_id GROUP BY bp.staff_id)p ON p.staff_id=d.id WHERE d.club_id=_club_id AND (d.active OR t.a IS NOT NULL OR p.a IS NOT NULL) ORDER BY d.label; END $$;
GRANT EXECUTE ON FUNCTION public.bar_staff_tip_balances(uuid,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_pay_staff_tips(_club_id uuid,_staff_id uuid,_amount numeric,_request_id uuid,_token uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n text;d uuid;balance numeric;prior bar_tip_payouts; BEGIN d:=_bar_tip_authorise(_club_id,_token); IF NOT EXISTS(SELECT 1 FROM club_bar_settings WHERE club_id=_club_id AND tips_enabled) THEN RAISE EXCEPTION 'Tips are not enabled'; END IF; IF _amount IS NULL OR _amount<=0 OR _amount::text IN ('NaN','Infinity','-Infinity') OR _amount<>round(_amount,2) OR _request_id IS NULL THEN RAISE EXCEPTION 'Invalid cash payout'; END IF; SELECT label INTO n FROM bar_counter_devices WHERE id=_staff_id AND club_id=_club_id FOR UPDATE; IF n IS NULL THEN RAISE EXCEPTION 'Staff not found'; END IF; SELECT * INTO prior FROM bar_tip_payouts WHERE id=_request_id; IF FOUND THEN IF prior.club_id<>_club_id OR prior.staff_id<>_staff_id OR prior.amount<>_amount THEN RAISE EXCEPTION 'Payout retry does not match'; END IF; RETURN; END IF; SELECT coalesce((SELECT sum(amount) FROM bar_tips WHERE club_id=_club_id AND staff_id=_staff_id AND status='earned'),0)-coalesce((SELECT sum(amount) FROM bar_tip_payouts WHERE club_id=_club_id AND staff_id=_staff_id),0) INTO balance; IF _amount>balance THEN RAISE EXCEPTION 'Cash payout exceeds unpaid tips'; END IF; INSERT INTO bar_tip_payouts(id,club_id,staff_id,staff_name,amount,actor_user_id,actor_device_id) VALUES(_request_id,_club_id,_staff_id,n,_amount,auth.uid(),d); INSERT INTO club_journal_entries(club_id,journal_ref,account,debit,credit,description) VALUES(_club_id,_request_id,'bar_cost_of_sales',_amount,0,'Tips paid — '||n),(_club_id,_request_id,'cash',0,_amount,'Tips paid — '||n); END $$;
GRANT EXECUTE ON FUNCTION public.bar_pay_staff_tips(uuid,uuid,numeric,uuid,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_counter_settle_with_tip(_tab_id uuid,_method text,_token uuid,_tip numeric,_staff_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t bar_guest_tabs;r jsonb;c uuid; BEGIN c:=bar_counter_context(_token,NULL); PERFORM _bar_tip_authorise(c,_token); SELECT * INTO t FROM bar_guest_tabs WHERE id=_tab_id AND club_id=c FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Tab not found'; END IF; IF t.status IN ('settled','closed') THEN RETURN jsonb_build_object('already',true); END IF; IF t.status='open' THEN PERFORM bar_set_tab_tip(t.id,t.token,_tip,_staff_id,_token); END IF; r:=bar_counter_settle_tab(t.id,_method,_token,NULL); RETURN r; END $$;
GRANT EXECUTE ON FUNCTION public.bar_counter_settle_with_tip(uuid,text,uuid,numeric,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_counter_account_with_tip(_tab_id uuid,_token uuid,_tip numeric,_staff_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t bar_guest_tabs;c uuid; BEGIN c:=bar_counter_context(_token,NULL); PERFORM _bar_tip_authorise(c,_token); SELECT * INTO t FROM bar_guest_tabs WHERE id=_tab_id AND club_id=c FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Tab not found'; END IF; IF t.status IN ('settled','closed') THEN RETURN jsonb_build_object('already',true); END IF; PERFORM bar_set_tab_tip(t.id,t.token,_tip,_staff_id,_token); RETURN bar_counter_charge_member_account(t.id,_token,NULL); END $$;
GRANT EXECUTE ON FUNCTION public.bar_counter_account_with_tip(uuid,uuid,numeric,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_request_settlement_with_tip(_tab_id uuid,_token uuid,_method text,_tip numeric,_staff_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t bar_guest_tabs; BEGIN SELECT * INTO t FROM bar_guest_tabs WHERE id=_tab_id AND token=_token FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Tab not found'; END IF; IF t.status='open' THEN PERFORM bar_set_tab_tip(t.id,t.token,_tip,_staff_id); END IF; RETURN settle_bar_guest_tab(t.id,t.token,_method); END $$;
GRANT EXECUTE ON FUNCTION public.bar_request_settlement_with_tip(uuid,uuid,text,numeric,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_qr_account_with_tip(_tab_id uuid,_token uuid,_club_member_id uuid,_pin text,_tip numeric,_staff_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE t bar_guest_tabs; BEGIN SELECT * INTO t FROM bar_guest_tabs WHERE id=_tab_id AND token=_token FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Tab not found'; END IF; PERFORM bar_set_tab_tip(t.id,t.token,_tip,_staff_id); RETURN bar_qr_charge_guest_tab_member(t.id,t.token,_club_member_id,_pin); END $$;
GRANT EXECUTE ON FUNCTION public.bar_qr_account_with_tip(uuid,uuid,uuid,text,numeric,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_qr_cart_account_with_tip(_code text,_lines jsonb,_club_member_id uuid,_pin text,_tip numeric,_staff_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE r jsonb;t uuid;tok uuid; BEGIN r:=open_bar_guest_tab(_code,'Member account'); t:=(r->>'tab_id')::uuid;tok:=(r->>'token')::uuid; PERFORM add_to_bar_guest_tab(t,tok,_lines); RETURN bar_qr_account_with_tip(t,tok,_club_member_id,_pin,_tip,_staff_id); END $$;
GRANT EXECUTE ON FUNCTION public.bar_qr_cart_account_with_tip(text,jsonb,uuid,text,numeric,uuid) TO anon,authenticated;
CREATE FUNCTION public.bar_terminal_cart_with_tip(_code text,_lines jsonb,_buyer_name text,_tip numeric,_staff_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb;t uuid;tok uuid;c uuid; BEGIN r:=record_bar_terminal_sale(_lines,_code,NULL,_buyer_name);t:=(r->>'tab_id')::uuid;tok:=(r->>'token')::uuid; SELECT club_id INTO c FROM bar_guest_tabs WHERE id=t AND token=tok FOR UPDATE; IF c IS NULL THEN RAISE EXCEPTION 'Tab not found'; END IF; PERFORM _bar_prepare_tip(c,t,NULL,_tip,_staff_id); UPDATE bar_tab_payment_events SET amount=amount+_tip WHERE tab_id=t AND action='requested'; RETURN get_bar_guest_tab(t,tok)||jsonb_build_object('token',tok); END $$;
GRANT EXECUTE ON FUNCTION public.bar_terminal_cart_with_tip(text,jsonb,text,numeric,uuid) TO anon,authenticated;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.get_bar_guest_tab(uuid,uuid)'::regprocedure) INTO d; d:=replace(d,'''lines'', v_lines, ''total'', v_total)', '''lines'', v_lines, ''subtotal'', v_total, ''tip'', coalesce((SELECT amount FROM public.bar_tips WHERE tab_id=_tab_id AND status<>''cancelled''),0), ''total'', v_total+coalesce((SELECT amount FROM public.bar_tips WHERE tab_id=_tab_id AND status<>''cancelled''),0))'); IF position('''subtotal''' in d)=0 THEN RAISE EXCEPTION 'Guest tab view extension did not match'; END IF; EXECUTE d; SELECT pg_get_functiondef('public.bar_counter_board(uuid,uuid)'::regprocedure) INTO d; d:=replace(d,'''total'', COALESCE((SELECT sum(s.total) FROM public.bar_visitor_sales s WHERE s.guest_tab_id = g.id), 0),', '''subtotal'', COALESCE((SELECT sum(s.total) FROM public.bar_visitor_sales s WHERE s.guest_tab_id = g.id), 0), ''tip'', coalesce((SELECT amount FROM public.bar_tips WHERE tab_id=g.id AND status<>''cancelled''),0), ''total'', COALESCE((SELECT sum(s.total) FROM public.bar_visitor_sales s WHERE s.guest_tab_id = g.id), 0)+coalesce((SELECT amount FROM public.bar_tips WHERE tab_id=g.id AND status<>''cancelled''),0),'); IF position('''subtotal''' in d)=0 THEN RAISE EXCEPTION 'Counter board extension did not match'; END IF; d:=replace(d,'''venue_code'', v_code,', '''venue_code'', v_code, ''tip_staff_id'', (SELECT device_id FROM public.bar_counter_sessions WHERE token=_token AND revoked_at IS NULL AND expires_at>now() AND club_id=v_club),'); EXECUTE d; END $$;
CREATE FUNCTION public._bar_tip_payment_amount() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.amount:=NEW.amount+coalesce((SELECT amount FROM bar_tips WHERE tab_id=NEW.tab_id AND status<>'cancelled'),0); RETURN NEW; END $$;
CREATE TRIGGER bar_tip_payment_amount BEFORE INSERT ON public.bar_tab_payment_events FOR EACH ROW EXECUTE FUNCTION public._bar_tip_payment_amount();
CREATE FUNCTION public._bar_tip_no_earned_reopen() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='open' AND OLD.status IN ('settled','closed') AND EXISTS(SELECT 1 FROM bar_tips WHERE tab_id=NEW.id AND status IN ('earned','account_due')) THEN RAISE EXCEPTION 'Paid tip tabs cannot be reopened; use an audited correction'; END IF; RETURN NEW; END $$;
CREATE TRIGGER bar_tip_no_earned_reopen BEFORE UPDATE OF status ON public.bar_guest_tabs FOR EACH ROW EXECUTE FUNCTION public._bar_tip_no_earned_reopen();
REVOKE ALL ON FUNCTION public._bar_tip_tab_state(),public._bar_tip_sale_state(),public._bar_tip_payment_amount(),public._bar_tip_no_earned_reopen() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE f record; BEGIN FOR f IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('bar_tip_config','bar_set_tip_switch','_bar_prepare_tip','bar_set_tab_tip','_bar_recognise_account_tips','_bar_tip_account_payment','_bar_earn_tip','_bar_tip_tab_state','_bar_tip_sale_state','_bar_tip_authorise','bar_staff_tip_balances','bar_pay_staff_tips','bar_counter_settle_with_tip','bar_counter_account_with_tip','bar_request_settlement_with_tip','bar_qr_account_with_tip','bar_qr_cart_account_with_tip','bar_terminal_cart_with_tip','_bar_tip_payment_amount','_bar_tip_no_earned_reopen') LOOP EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC',f.signature); END LOOP; END $$;